public static void zamien(int tab[], int j) {
    // zamienia sąsiadów: szufladę j - 1 i szufladę j
    int tmp = tab[j - 1];
    tab[j - 1] = tab[j];
    tab[j] = tmp;
}

public static void wypisz(int tab[], int nr) {
    System.out.print("po przejsciu " + nr + ":");
    for (int k = 0; k < tab.length; k++) {
        System.out.print(" " + tab[k]);
    }
    System.out.println();
}

public static void main(String[] args) {
    int tab[] = {3, 6, 2, 1};
    // przejście 0: pary (0,1), (1,2), (2,3) - zamieniaj tylko te, gdzie lewy jest większy
    // np. zamien(tab, 2); zamienia szuflady 1 i 2

    wypisz(tab, 0);
    // przejście 1

    wypisz(tab, 1);
    // przejście 2

    wypisz(tab, 2);
    // przejście 3

    wypisz(tab, 3);
}

