        for (int j = 1; j < n - i; j++) {
            if (imiona.get(j - 1).compareTo(imiona.get(j)) > 0) {
                String tmp = imiona.get(j - 1);
                imiona.set(j - 1, imiona.get(j));
                imiona.set(j, tmp);
            }
        }
    }
}

